// Incremental, memory-bounded aggregation. Runs once per batch (<=1000 rows).
const sd = $getWorkflowStaticData('global');

// Fresh start on the first batch of this execution (guards against stale state from a crashed run)
if ($runIndex === 0) {
  sd.dcAgg = { groups: {}, rowsAnalyzed: 0, catKey: null, valKey: null };
}
const agg = sd.dcAgg || (sd.dcAgg = { groups: {}, rowsAnalyzed: 0, catKey: null, valKey: null });

const rows = $input.all().map(i => i.json).filter(r => r && typeof r === 'object');

if (rows.length) {
  // Detect category/value columns once, from the first non-empty batch
  if (!agg.catKey) {
    const META = /(^|_)(id|uuid|guid|internal|meta|hash|token|created|updated|modified|timestamp)($|_)?/i;
    const keys = Object.keys(rows[0]);
    const keepKeys = keys.filter(k => !META.test(k));
    const isNum = v => v !== null && v !== undefined && String(v).trim() !== '' && !isNaN(Number(String(v).replace(/[^0-9.\-]/g, '')));
    agg.catKey = keepKeys.find(k => !isNum(rows[0][k])) || keepKeys[0];
    agg.valKey = keepKeys.find(k => isNum(rows[0][k]) && k !== agg.catKey) || keepKeys.find(k => k !== agg.catKey) || keepKeys[0];
  }
  const catKey = agg.catKey, valKey = agg.valKey;
  for (const r of rows) {
    const cat = (r[catKey] !== undefined && r[catKey] !== null && String(r[catKey]).trim() !== '') ? String(r[catKey]) : 'Uncategorized';
    const num = Number(String(r[valKey]).replace(/[^0-9.\-]/g, '')) || 0;
    if (!agg.groups[cat]) agg.groups[cat] = { category: cat, total: 0, count: 0 };
    agg.groups[cat].total += num;
    agg.groups[cat].count += 1;
  }
  agg.rowsAnalyzed += rows.length;
}

// Pass the batch through so Save Dataset Rows can bulk-insert it
return $input.all();

